-- =====================================================================
-- 0036 — Controle de conteúdo das LPs: importa a aba LP´s
-- da planilha "Controle de Lp´s e Epic Pages" (2943 itens).
-- Cada célula vira um registro (LP, elemento, situação, versão = nome da aba).
-- Só entram LPs que já existem em Landing Pages (nome comparado sem acento,
-- caixa ou pontuação). As que não forem encontradas aparecem na mensagem final.
-- Pode rodar mais de uma vez (não duplica). Rode DEPOIS da 0014 e 0016/0017.
-- =====================================================================

create or replace function public.norm_nome(t text)
returns text language sql immutable as $f$
  select trim(regexp_replace(
    translate(lower(coalesce(t, '')),
      'áàâãäéèêëíìîïóòôõöúùûüçñ', 'aaaaaeeeeiiiiooooouuuucn'),
    '[^a-z0-9]+', ' ', 'g'))
$f$;

drop table if exists tmp_controle_lps;
create temp table tmp_controle_lps as
select e->>0 as lp, e->>1 as elemento, e->>2 as conteudo, e->>3 as versao
